@startuml

class Tutor {
  + name : string
  + email : string
  + bankAccount : string
}

class Student {
  + name : string
  + email : string
}

class TutoringOffer {
  + subject : string
  + expertiseLevel : string
  + hourlyPrice : float
}

class Availability {
  + dayOfWeek : string
  + startTime : time
  + endTime : time
}

class TutoringRequest {
  + targetDate : date
  + targetTime : time
  + expertiseLevel : string
}

class TutoringSession {
  + sessionDate : date
  + sessionTime : time
  + isCancelled : boolean
  + cancellationReason : string
  + paymentMethod : string
  + finalPrice : float
}

Tutor "1" -- "*" TutoringOffer
Tutor "1" -- "*" Availability
Tutor "1" -- "*" TutoringRequest
Tutor "1" -- "*" TutoringSession
Student "1" -- "*" TutoringRequest
Student "1" -- "*" TutoringSession
TutoringRequest "1" -- "0..1" TutoringSession
TutoringOffer "*" -- "1" Tutor
TutoringOffer "*" -- "1" Student : browses
TutoringSession "*" -- "1" Tutor
TutoringSession "*" -- "1" Student

@enduml

